H.background();
const a = P.a;            // the point we test continuity at
const jump = P.jump;      // size of the jump in the function value at x=a
const hole = P.hole;      // >=0.5 = leave a hole (f(a) undefined), else filled
const v = H.plot2d({ xMin: -6, xMax: 6, yMin: -4, yMax: 6 });
v.grid(); v.axes();
// Left branch approaches L; right branch starts at L+jump.
const L = 1;
function left(x){ return L + 0.5 * (x - a); }
function right(x){ return L + jump + 0.5 * (x - a); }
v.fn(x => (x < a ? left(x) : NaN), { color: H.colors.accent, width: 3 });
v.fn(x => (x > a ? right(x) : NaN), { color: H.colors.accent2, width: 3 });
v.line(a, -4, a, 6, { color: H.colors.violet, width: 1, dash: [4, 4] });
const continuous = Math.abs(jump) < 0.05 && hole < 0.5;
// Open circles mark the one-sided limits; a filled dot marks f(a) if defined.
v.circle(a, L, 5.5, { stroke: H.colors.good, width: 2, fill: H.colors.bg });
v.circle(a, L + jump, 5.5, { stroke: H.colors.accent2, width: 2, fill: H.colors.bg });
if (hole < 0.5) v.dot(a, L + jump, { r: 6, fill: continuous ? H.colors.good : H.colors.warn });
// Animate a tracer crossing x=a so a jump shows as a sudden change in height.
const xs = 4 * Math.sin(t * 0.7);
const ys = xs < a ? left(xs) : right(xs);
if (Number.isFinite(ys)) v.dot(xs, ys, { r: 5, fill: H.colors.yellow });
H.text("Continuity at x = a:  lim f = f(a)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("a = " + a.toFixed(1) + "   jump = " + jump.toFixed(2) + "   hole = " + (hole >= 0.5 ? "yes" : "no"), 24, 52, { color: H.colors.sub, size: 13 });
const reason = hole >= 0.5 ? "f(a) undefined (hole)" : Math.abs(jump) >= 0.05 ? "left limit != right limit (jump)" : "left=right=f(a): continuous";
H.text((continuous ? "CONTINUOUS — " : "DISCONTINUOUS — ") + reason, 24, 74, { color: continuous ? H.colors.good : H.colors.warn, size: 13, weight: 700 });
H.legend([{ label: "left branch", color: H.colors.accent }, { label: "right branch", color: H.colors.accent2 }], H.W - 170, 28);
